        'sawyer' => ['name' => 'Sawyer', 'kind' => self::PROCESSING, 'source' => 'woodcutting', 'palette' => 'wood', 'description' => 'Saws wood into planks. The first bench a prospector ever stands at, and the one the opening arc ends on.'],
